  <g data-part="heart">
    <path d="M53 42 Q58 38 61 43 Q64 49 58 54 L53 58 L48 53 Q43 47 47 42 Q50 39 53 42 Z" fill="#7a2631" stroke="rgba(0,0,0,.45)" stroke-width=".8"/>
  </g>
  <g data-part="head">
