    <circle cx="82" cy="83" r="2.6" fill="#8a6a4a" stroke="rgba(0,0,0,.5)" stroke-width=".7"/>
  </g>
</svg>`;

export function integrityColor(v) {
  if (v >= 75) return '#6b573e';
  if (v >= 50) return '#8a6a35';
  if (v >= 25) return '#a8632e';
  return '#b3352b';
}

export function paintBody(container, body) {
  if (!container) return;
  for (const [part, val] of Object.entries(body)) {
    const els = container.querySelectorAll(`[data-part="${part}"]`);
    const color = integrityColor(val);
    els.forEach(el => {
      el.style.fill = color;
      el.style.filter = val < 22 ? 'drop-shadow(0 0 4px rgba(220,50,40,.65))' : '';
    });
  }
}

export function bodyPartList(body) {
  const order = ['head', 'neck', 'chest', 'heart', 'abdomen', 'arms', 'legs', 'joints'];
  return order.map(p => {
    const v = Math.round(body[p]);
    const cls = v < 25 ? 'crit' : v < 55 ? 'injured' : '';
    return `<div class="part-item ${cls}" title="${BODY_PARTS[p]?.effects || ''}"><span>${BODY_PARTS[p]?.label || p}</span><b>${v}</b></div>`;
  }).join('');
}

export function pipsMarkup(cur, max) {
  let out = '';
  for (let i = 0; i < max; i++) out += `<span class="pip ${i < cur ? 'on' : ''}"></span>`;
  return out;
}

export function debounce(fn, ms) {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
}

/* Directional swipe + timing reaction challenge overlay. */

import { arrowFor, partLabel, DIRECTION_BY_PART } from './helpers.js';
import { sound } from './audio.js';

const DIRS = ['left', 'up', 'down', 'right'];

function qualityText(mode, q) {
  if (mode === 'attack') {
    if (q === 'perfect') return ['PERFECT', '142% DAMAGE · THE BODY OPENS'];
    if (q === 'good') return ['CLEAN', '100% DAMAGE · SOLID CONNECTION'];
    if (q === 'weak') return ['GLANCING', '66% DAMAGE · OFF BALANCE'];
    return ['OFF BALANCE', '34% DAMAGE · THE ANGLE IS LOST'];
  }
  if (q === 'perfect') return ['PERFECT READ', 'NO DAMAGE · COUNTER WINDOW OPEN'];
  if (q === 'good') return ['SOLID GUARD', '34% DAMAGE TAKEN'];
  if (q === 'weak') return ['GRAZED', '72% DAMAGE TAKEN'];
  return ['HIT CLEAN', '108% DAMAGE TAKEN'];
}

export function runReaction({ mode = 'attack', card, params, enemyName = '' }) {
  return new Promise(resolve => {
    const required = mode === 'attack'
      ? (DIRECTION_BY_PART[card.part] || 'left')
      : DIRS[Math.floor(Math.random() * DIRS.length)];
    const perfectW = Math.min(34, params.perfect * 200);
    const goodW = Math.min(64, params.good * 200);
    const overlay = document.createElement('div');
    overlay.className = `overlay reaction-overlay ${mode}`;
    overlay.innerHTML = `
      <div class="reaction-speedlines"></div>
      <div class="reaction-content">
        <div class="reaction-kicker">${mode === 'attack' ? 'STRIKE WINDOW' : 'INCOMING ATTACK'} · ${card.name.toUpperCase()}</div>
        <div class="reaction-title">${mode === 'attack' ? 'SWIPE & <em>STRIKE</em>' : 'READ & <em>DEFEND</em>'}</div>
        <div class="reaction-meta">${mode === 'attack' ? 'TARGET' : 'ATTACKER'} <b>${mode === 'attack' ? partLabel(card.part) : enemyName.toUpperCase()}</b> &nbsp;·&nbsp; ${mode === 'attack' ? `${card.dmg} BASE DAMAGE` : `${partLabel(card.part)} TARGETED`} &nbsp;·&nbsp; SPEED <b>${params.speed.toFixed(2)}×</b></div>
        <div class="reaction-dir-wrap">
          <div class="reaction-dir-label">REQUIRED DIRECTION</div>
          <div class="direction-pad">
            <button class="dir-arrow" data-dir="left" aria-label="Swipe left">←<small>LEFT</small></button>
            <button class="dir-arrow" data-dir="up" aria-label="Swipe up">↑<small>UP</small></button>
            <button class="dir-arrow" data-dir="down" aria-label="Swipe down">↓<small>DOWN</small></button>
            <button class="dir-arrow" data-dir="right" aria-label="Swipe right">→<small>RIGHT</small></button>
          </div>
        </div>
        <div class="timing-wrap">
          <div class="timing-track" id="timingTrack">
            <div class="timing-zone good" style="left:${50 - goodW / 2}%;width:${goodW}%"></div>
            <div class="timing-zone perfect" style="left:${50 - perfectW / 2}%;width:${perfectW}%"></div>
            <div class="timing-marker" id="timingMarker" style="left:0%"></div>
          </div>
          <div class="timing-scale"><span>TOO EARLY</span><span>PERFECT BAND</span><span>TOO LATE</span></div>
        </div>
        <div class="reaction-instruction">
          Swipe or press <span class="key">${arrowFor[required]}</span> in the <b>${arrowFor[required]} ${required.toUpperCase()}</b> direction, and release inside the band.<br>
          ${mode === 'attack' ? 'A clean read multiplies damage. Hesitation is punished.' : 'A clean read takes no damage. A perfect read with a counter stance answers automatically.'}
        </div>
        <button class="btn btn-primary reaction-tap" id="tapTime">TAP TO TIME</button>
        <div class="reaction-result hidden" id="reactionResult"><div class="rr-quality"></div><div class="rr-sub"></div></div>
      </div>`;

    document.getElementById('overlayRoot').appendChild(overlay);
    const marker = overlay.querySelector('#timingMarker');
    const result = overlay.querySelector('#reactionResult');
    const qualityEl = result.querySelector('.rr-quality');
    const subEl = result.querySelector('.rr-sub');
    overlay.querySelectorAll('.dir-arrow').forEach(btn => {
      if (btn.dataset.dir === required) btn.classList.add('required');
      btn.addEventListener('click', ev => {
        ev.stopPropagation();
        judge(btn.dataset.dir);
      });
      btn.addEventListener('pointerdown', ev => ev.stopPropagation());
    });
    overlay.querySelector('#tapTime').addEventListener('pointerdown', ev => ev.stopPropagation());
    overlay.querySelector('#tapTime').addEventListener('click', ev => {
      ev.stopPropagation();
      judge(required);
    });

    const start = performance.now();
    const sweep = 1080 / Math.max(0.6, params.speed);
    const timeout = start + sweep * 4.1;
    let raf = 0;
    let done = false;
    let dragStart = null;

    const markerPos = (now) => {
      const elapsed = now - start;
      const phase = (elapsed % (sweep * 2)) / sweep;
      return phase <= 1 ? phase : 2 - phase;
    };

    const frame = (now) => {
      if (done) return;
      if (now > timeout) { judge(required, true); return; }
      marker.style.left = `${(markerPos(now) * 100).toFixed(2)}%`;
      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);

    const dirFromDelta = (dx, dy) => {
      if (Math.abs(dx) > Math.abs(dy)) return dx > 0 ? 'right' : 'left';
      return dy > 0 ? 'down' : 'up';
    };

    overlay.addEventListener('pointerdown', ev => {
      if (done || ev.target.closest('button')) return;
      dragStart = { x: ev.clientX, y: ev.clientY };
    });
    overlay.addEventListener('pointerup', ev => {
      if (done || ev.target.closest('button') || !dragStart) return;
      const dx = ev.clientX - dragStart.x;
      const dy = ev.clientY - dragStart.y;
      dragStart = null;
      if (Math.hypot(dx, dy) < 22) judge(required);
      else judge(dirFromDelta(dx, dy));
    });

    const onKey = ev => {
      if (done) return;
      const map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down', a: 'left', d: 'right', w: 'up', s: 'down' };
      if (ev.key === ' ') { ev.preventDefault(); judge(required); return; }
      const d = map[ev.key];
      if (d) { ev.preventDefault(); judge(d); }
    };
    window.addEventListener('keydown', onKey, true);

    function cleanup() {
      cancelAnimationFrame(raf);
      window.removeEventListener('keydown', onKey, true);
    }

    function judge(dir, timedOut = false) {
      if (done) return;
      done = true;
      cleanup();
      const p = Math.min(1, Math.max(0, markerPos(performance.now())));
      marker.style.left = `${(p * 100).toFixed(2)}%`;
      const dist = Math.abs(p - 0.5);
      let q;
      if (timedOut || dist > 0.43) q = 'fail';
      else if (dir !== required) q = 'fail';
      else if (dist <= params.perfect) q = 'perfect';
      else if (dist <= params.good) q = 'good';
      else q = 'weak';
      const [title, sub] = qualityText(mode, q);
      qualityEl.textContent = title;
      subEl.textContent = timedOut ? 'TOO SLOW · THE WINDOW CLOSES' : dir !== required ? `WRONG DIRECTION · EXPECTED ${required.toUpperCase()}` : sub;
      result.classList.remove('hidden');
      result.classList.toggle('bad', q === 'weak' || q === 'fail');
      if (q === 'perfect') sound.perfect();
      else if (q === 'fail') sound.fail();
      else sound.click();
      setTimeout(() => {
        overlay.classList.add('closing');
        setTimeout(() => {
          overlay.remove();
          resolve(q);
        }, 170);
      }, 760);
    }
  });
}

/* Combat HUD: bars, anatomy, status, hand, log, banners. */

import { STYLES } from './data.js';
import { miniPortraitSVG } from './art.js';
import { bodyPartList, cardMarkup, paintBody, pipsMarkup, tooltipMarkup, typeLabel, partLabel } from './helpers.js';

const $ = id => document.getElementById(id);

export class CombatHUD {
  constructor(renderer) {
    this.renderer = renderer;
    this.names = { player: 'KAI', enemy: 'OPPONENT' };
    this.logs = [];
    this.onPlay = null;
    this.onEndTurn = null;
    this.onCardHover = null;
    this.combat = null;
    this.handSig = '';
    this.bodyInit = false;
    this.bind();
  }

  bind() {
    this.handEl = $('hand');
    this.handEl.addEventListener('click', ev => {
      const el = ev.target.closest('.tcard');
      if (!el || !this.combat || el.classList.contains('disabled')) return;
      const card = this.combat.hand.find(c => c.uid === el.dataset.uid);
      if (card && this.onPlay) this.onPlay(card);
    });
    this.handEl.addEventListener('mouseover', ev => {
      const el = ev.target.closest('.tcard');
      if (!el || !this.combat) return;
      const card = this.combat.hand.find(c => c.uid === el.dataset.uid);
      if (card) this.showTooltip(card, el.getBoundingClientRect());
    });
    this.handEl.addEventListener('mouseout', ev => {
      if (ev.target.closest('.tcard')) this.hideTooltip();
    });
    $('endTurnBtn').addEventListener('click', () => this.onEndTurn?.());
    $('logToggle').parentElement.addEventListener('click', () => {
      $('combatLog').classList.toggle('collapsed');
      $('logToggle').textContent = $('combatLog').classList.contains('collapsed') ? '+' : '−';
    });
  }

  reset(names) {
    this.names = names || this.names;
    this.logs = [];
    $('logEntries').innerHTML = '';
    this.bodyInit = false;
    $('playerBody').innerHTML = '';
    $('enemyBody').innerHTML = '';
    $('playerPortrait').innerHTML = '';
    $('enemyPortrait').innerHTML = '';
    this.hideIncoming();
    $('combatLog').classList.remove('collapsed');
  }

  configure(meta) {
    this.names = meta.names || this.names;
    const pStyle = STYLES[meta.player?.style] || STYLES.shaolin;
    const eStyle = STYLES[meta.enemy?.style] || STYLES.shaolin;
    $('playerPortrait').innerHTML = miniPortraitSVG(meta.player?.style || 'shaolin', meta.player?.look || pStyle.look);
    $('enemyPortrait').innerHTML = miniPortraitSVG(meta.enemy?.style || 'shaolin', meta.enemy?.look || eStyle.look);
    $('playerBody').innerHTML = '';
    $('enemyBody').innerHTML = '';
    this.bodyInit = false;
    $('playerHud').style.setProperty('--accent', pStyle.color);
    $('enemyHud').style.setProperty('--accent', eStyle.color);
  }

  update(combat) {
    if (!combat) return;
    this.combat = combat;
    const p = combat.player, e = combat.enemy;
    const pStyle = STYLES[p.style] || STYLES.shaolin;
    const eStyle = STYLES[e.style] || STYLES.shaolin;

    $('playerName').textContent = this.names.player.toUpperCase();
    $('enemyName').textContent = this.names.enemy.toUpperCase();
    $('playerStyle').textContent = `${pStyle.name.toUpperCase()} · LV ${p.level}`;
    $('enemyStyle').textContent = `${eStyle.name.toUpperCase()} · LV ${e.level}`;

    this.setBar('playerHp', p.hp, p.maxHp);
    this.setBar('playerSta', p.stamina, p.maxStamina);
    this.setBar('enemyHp', e.hp, e.maxHp);
    this.setBar('enemySta', e.stamina, e.maxStamina);
    $('playerHpNum').textContent = `${Math.max(0, Math.round(p.hp))}`;
    $('playerStaNum').textContent = `${Math.max(0, Math.round(p.stamina))}`;
    $('enemyHpNum').textContent = `${Math.max(0, Math.round(e.hp))}`;
    $('enemyStaNum').textContent = `${Math.max(0, Math.round(e.stamina))}`;

    $('playerChi').innerHTML = pipsMarkup(p.chi, p.maxChi);
    $('enemyChi').innerHTML = pipsMarkup(e.chi, e.maxChi);
    $('playerFocus').textContent = p.statuses.focus > 0 ? `FOCUS +${Math.round(p.statuses.focus * 100)}%` : '';
    $('enemyFocus').textContent = e.statuses.guard > 0 ? `GUARD ${Math.round(e.statuses.guard * 100)}%` : '';

    if (!this.bodyInit) {
      $('playerBody').innerHTML = (this.bodyTemplate || '');
      $('enemyBody').innerHTML = (this.bodyTemplate || '');
      this.bodyInit = true;
    }
    if (!this.bodyTemplate) {
      import('./helpers.js').then(h => {
        this.bodyTemplate = h.BODY_SVG;
        $('playerBody').innerHTML = h.BODY_SVG;
        $('enemyBody').innerHTML = h.BODY_SVG;
        paintBody($('playerBody'), p.body);
        paintBody($('enemyBody'), e.body);
      });
    }
    paintBody($('playerBody'), p.body);
    paintBody($('enemyBody'), e.body);
    $('playerParts').innerHTML = bodyPartList(p.body);
    $('enemyParts').innerHTML = bodyPartList(e.body);
    $('playerStatus').innerHTML = combat.statusList('player').map(s => `<span class="status-chip" style="color:${s.color}">${s.label}</span>`).join('');
    $('enemyStatus').innerHTML = combat.statusList('enemy').map(s => `<span class="status-chip" style="color:${s.color}">${s.label}</span>`).join('');

    const pStance = p.statuses.counter ? 'COUNTER READY' : p.statuses.guard > 0 ? 'GUARD SET' : p.statuses.focus > 0 ? 'FOCUSED' : 'STANCE';
    const pStanceEl = $('playerStance');
    pStanceEl.textContent = pStance;
    pStanceEl.className = `stance-pill ${p.statuses.counter ? 'counter' : p.statuses.guard > 0 ? 'guard' : ''}`;
    const eStanceEl = $('enemyStance');
    eStanceEl.textContent = e.statuses.counter ? 'COUNTER STANCE' : e.statuses.guard > 0 ? `GUARD ${Math.round(e.statuses.guard * 100)}%` : 'OPPONENT';
    eStanceEl.className = `stance-pill ${e.statuses.counter ? 'counter' : e.statuses.guard > 0 ? 'guard' : ''}`;

    $('roundNum').textContent = combat.turn;
    const phaseEl = $('phaseText');
    if (combat.over) { phaseEl.textContent = 'FINISHED'; phaseEl.className = 'tb-phase'; }
    else if (combat.phase === 'enemy') { phaseEl.textContent = 'ENEMY TURN'; phaseEl.className = 'tb-phase enemy'; }
    else { phaseEl.textContent = combat.busy ? 'RESOLVING' : 'YOUR MOVE'; phaseEl.className = 'tb-phase'; }

    $('energyNum').textContent = `${p.chi} / ${p.maxChi}`;
    $('deckCount').textContent = `DECK ${combat.drawPile.length}`;
    $('discardCount').textContent = `DISCARD ${combat.discard.length}`;
    $('handHint').textContent = combat.over ? 'FIGHT OVER' : combat.phase === 'enemy' ? 'READ THE ATTACK' : combat.busy ? '...' : 'SELECT A TECHNIQUE';
    $('endTurnBtn').disabled = combat.busy || combat.phase !== 'player' || combat.over;

    this.renderHand(combat);
    this.updateLooks(combat);
  }

  setBar(prefix, cur, max) {
    const pct = Math.max(0, Math.min(100, (cur / max) * 100));
    const bar = $(`${prefix}Bar`);
    const ghost = $(`${prefix}Ghost`);
    if (bar) bar.style.width = `${pct}%`;
    if (ghost) ghost.style.width = `${pct}%`;
  }

  updateLooks(combat) {
    const apply = (side, f) => {
      const s = this.renderer.sides[side];
      if (!s.look) return;
      s.look.blood = f.body.head < 68 || f.body.chest < 45;
      s.look.sweat = f.stamina / f.maxStamina < 0.5 || f.hp / f.maxHp < 0.5;
    };
    apply('player', combat.player);
    apply('enemy', combat.enemy);
    this.renderer.setCondition('player', combat.player.body);
    this.renderer.setCondition('enemy', combat.enemy.body);
  }

  renderHand(combat) {
    const sig = `${combat.hand.map(c => c.uid).join(',')}|${combat.player.chi}|${combat.player.stamina}|${combat.phase}|${combat.busy}|${combat.over}`;
    if (sig === this.handSig) return;
    this.handSig = sig;
    const scroll = this.handEl.scrollLeft;
    if (!combat.hand.length) {
      this.handEl.innerHTML = '';
      $('handEmpty').classList.remove('hidden');
    } else {
      $('handEmpty').classList.add('hidden');
      this.handEl.innerHTML = combat.hand.map(card => {
        const ok = combat.canPlay(card).ok;
        return cardMarkup(card, { uid: card.uid, disabled: !ok });
      }).join('');
    }
    this.handEl.scrollLeft = scroll;
  }

  showTooltip(card, rect) {
    if (window.innerWidth < 760) return;
    const tt = $('tooltip');
    tt.innerHTML = tooltipMarkup(card);
    tt.classList.remove('hidden');
    const w = 286, h = tt.offsetHeight || 200;
    let x = rect.right + 12;
    if (x + w > window.innerWidth - 10) x = rect.left - w - 12;
    let y = Math.min(window.innerHeight - h - 12, Math.max(70, rect.top - 10));
    tt.style.left = `${Math.max(8, x)}px`;
    tt.style.top = `${y}px`;
  }

  hideTooltip() {
    $('tooltip').classList.add('hidden');
  }

  log(msg, kind = '') {
    if (!msg) return;
    this.logs.push({ msg, kind });
    if (this.logs.length > 30) this.logs.shift();
    const entries = this.logs.slice(-7).reverse().map(l => `<div class="log-entry ${l.kind}">${l.msg}</div>`).join('');
    $('logEntries').innerHTML = entries;
  }

  banner(title, sub = '', kind = '') {
    const host = $('screen-combat');
    host.querySelectorAll('.arena-banner').forEach(n => n.remove());
    const el = document.createElement('div');
    el.className = `arena-banner ${kind}`;
    const kicker = kind === 'bad' ? 'THE TIDE TURNS' : kind === 'enemy' ? 'OPPONENT PHASE' : kind === 'perfect' ? 'FLAWLESS' : kind === 'turn' ? 'COMBAT' : 'IRON LOTUS';
    el.innerHTML = `<div class="ab-kicker">${kicker}</div><div class="ab-title">${title}</div><div class="ab-sub">${sub}</div>`;
    host.appendChild(el);
    setTimeout(() => el.remove(), 1650);
  }

  showIncoming(card, enemyName) {
    const b = $('incomingBanner');
    b.classList.remove('hidden');
    $('incomingName').textContent = card.name.toUpperCase();
    $('incomingPart').textContent = `${partLabel(card.part)} · ${enemyName.toUpperCase()}`;
  }

  hideIncoming() {
    $('incomingBanner')?.classList.add('hidden');
  }

  showTurnPhase(phase, round) {
    $('roundNum').textContent = round;
    const el = $('phaseText');
    el.textContent = phase === 'enemy' ? 'ENEMY TURN' : 'YOUR MOVE';
    el.className = `tb-phase ${phase === 'enemy' ? 'enemy' : ''}`;
  }
}

